import csv
from pathlib import Path

import numpy as np
import pytest

FIXTURES = Path(__file__).parent / "fixtures"

TOLERANCE = 1e-12


def read_fixture(name):
    """Reads a CSV generated by experiments/08-python-fixtures.R as a dictionary of columns.

    The first line, a comment, records the source commit. R writes NA, NaN, Inf and -Inf
    in full; NA becomes NaN, because the two forms of undefined value count as a match
    for each other.
    """
    with open(FIXTURES / name, encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(line for line in handle if not line.startswith("#")))
    return {column: [row[column] for row in rows] for column in rows[0]}


def numeric(values):
    return np.array([np.nan if value == "NA" else float(value) for value in values])


def assert_same(actual, expected, context=""):
    actual = np.asarray(actual, dtype=np.float64)
    expected = np.asarray(expected, dtype=np.float64)
    both_undefined = np.isnan(actual) & np.isnan(expected)
    close = np.isclose(actual, expected, rtol=TOLERANCE, atol=TOLERANCE)
    wrong = ~(both_undefined | close)
    if wrong.any():
        k = np.flatnonzero(wrong)[:5]
        raise AssertionError(
            f"{context}: {wrong.sum()} valores diferentes; posições {k.tolist()}, "
            f"obtido {actual.ravel()[k].tolist()}, esperado {expected.ravel()[k].tolist()}")


@pytest.fixture(scope="session")
def gatto_grid():
    return read_fixture("gatto2021-grade.csv")


@pytest.fixture(scope="session")
def registry_grid():
    return read_fixture("registro-grade.csv")


@pytest.fixture(scope="session")
def registry_birds():
    return read_fixture("registro-birds.csv")


@pytest.fixture(scope="session")
def grid_counts(gatto_grid):
    return tuple(numeric(gatto_grid[column]) for column in "abcd")
